/* Generated by ./builder snapshot; edit NanoC sources instead. */
// Canonical source formatting is lexical and never executes macros or CT programs.

#include "nanoc/nanoc.h"

// Writes canonical indentation while retaining raw-island contents and literal token bytes.
static void format_indent(NcContext *c, NcBuffer *out, size_t width) {
    while (out->n && (out->v[out->n - 1] == ' ' || out->v[out->n - 1] == '\t')) {
        --out->n;
        out->v[out->n] = 0;
    }
    for (size_t i = 0; i < width; ++i) {
        nc_add(c, out, " ");
    }
}

// Formats spacing outside literals and C islands, with two spaces per indentation level.
char *nc_format_source(NcContext *c, const char *input) {
    NcTokens tokens = nc_lex(c, input, 1);
    NcBuffer out = {0};
    size_t levels[513] = {0};
    size_t depth = 0, groups = 0, group_base = 0, newlines = 0;
    bool bol = 1, space = 0;
    for (size_t i = 0; i < tokens.n; ++i) {
        NcToken token = tokens.v[i];
        bool comment = token.kind == NC_SPACE && token.n && token.s[0] == '/';
        if (token.kind == NC_SPACE && !comment) {
            for (size_t j = 0; j < token.n; ++j) {
                if (token.s[j] == '\n') {
                    if (out.n && newlines < 2) {
                        nc_add(c, &out, "\n");
                        ++newlines;
                    }
                    bol = 1;
                    space = 0;
                } else if (!bol) {
                    space = 1;
                }
            }
            continue;
        }
        if (bol) {
            size_t indent = (size_t)(token.column - 1);
            size_t desired = depth * 2;
            if (groups) {
                bool closing = nc_is(token, ")") || nc_is(token, "]") || nc_is(token, "}");
                desired = 2 * (group_base + (closing && groups == 1 ? 0 : 1));
            } else if (comment) {
                size_t at = depth;
                while (at && indent < levels[at]) {
                    --at;
                }
                desired = 2 * (at + (indent > levels[at] ? 1 : 0));
            } else {
                while (depth && indent < levels[depth]) {
                    --depth;
                }
                if (indent > levels[depth]) {
                    if (depth == 512) {
                        nc_fail(c, token.line, "formatter indentation depth limit exceeded");
                    }
                    levels[++depth] = indent;
                } else if (indent != levels[depth]) {
                    nc_fail(c, token.line, "inconsistent indentation");
                }
                desired = depth * 2;
            }
            format_indent(c, &out, desired);
            bol = 0;
            space = 0;
        } else if (space) {
            nc_add(c, &out, " ");
            space = 0;
        }
        if (nc_is(token, "@")) {
            NcCursor raw = {c, tokens, i + 1};
            if (nc_header_eat(&raw, "c", token.line)) {
                (void)nc_raw_read(c, &raw);
                char *text = nc_join(c, nc_slice(tokens, i, raw.pos));
                nc_add(c, &out, text);
                size_t n = strlen(text);
                bol = n && text[n - 1] == '\n';
                newlines = bol ? 1 : 0;
                i = raw.pos - 1;
                continue;
            }
        }
        nc_addn(c, &out, token.s, token.n);
        bol = token.n && token.s[token.n - 1] == '\n';
        newlines = bol ? 1 : 0;
        if (token.kind == NC_PUNCT) {
            if (nc_is(token, "(") || nc_is(token, "[") || nc_is(token, "{")) {
                if (!groups) {
                    group_base = depth;
                }
                ++groups;
            } else if (nc_is(token, ")") || nc_is(token, "]") || nc_is(token, "}")) {
                if (!groups) {
                    nc_fail(c, token.line, "unmatched closing delimiter");
                }
                --groups;
            }
        }
    }
    if (groups) {
        nc_fail(c, 1, "unterminated delimiter in formatter input");
    }
    while (out.n && (out.v[out.n - 1] == ' ' || out.v[out.n - 1] == '\t' || out.v[out.n - 1] == '\n' || out.v[out.n - 1] == '\r')) {
        --out.n;
    }
    if (out.n) {
        nc_add(c, &out, "\n");
    } else {
        nc_add(c, &out, "");
    }
    return out.v;
}

// Implements read-only formatting, in-place formatting, and CI idempotence checking.
int nc_format_command(NcContext *c, int argc, const char **argv) {
    const char *input = NULL;
    bool write = 0, check = 0, json = 0;
    for (int i = 2; i < argc; ++i) {
        if (!strcmp(argv[i], "--write")) {
            write = 1;
        } else if (!strcmp(argv[i], "--check")) {
            check = 1;
        } else if (!strcmp(argv[i], "--json")) {
            json = 1;
        } else if (!input) {
            input = argv[i];
        } else {
            nc_fail(c, 0, "unexpected formatter argument: %s", argv[i]);
        }
    }
    if (!input) {
        nc_fail(c, 0, "fmt requires a NanoC file");
    }
    c->file = input;
    char *source = nc_read(c, input);
    char *formatted = nc_format_source(c, source);
    bool changed = strcmp(source, formatted) != 0;
    if (write && changed) {
        nc_write(c, input, formatted);
    }
    if (json) {
        NcJson w;
        jw_start(&w, stdout);
        jw_open(&w, '{');
        jw_ki(&w, "schemaVersion", 1);
        jw_kb(&w, "changed", changed);
        jw_ki(&w, "bytes", (long)strlen(formatted));
        jw_close(&w, '}');
        fputc('\n', stdout);
    } else if (!write && !check) {
        fputs(formatted, stdout);
    }
    return check && changed ? 1 : 0;
}
